import json
from collections import Counter

def compute_fire_rates(path, label=""):
    lf_stats = {}
    total = 0
    total_non_short = 0
    with open(path) as f:
        for line in f:
            row = json.loads(line)
            total += 1
            if row.get("short_trajectory", False):
                continue
            total_non_short += 1
            for lf_name, val in row["labels"].items():
                if lf_name not in lf_stats:
                    lf_stats[lf_name] = {"fired": 0, "abstain": 0, "progress": 0, "stagnation": 0}
                if val == -1:
                    lf_stats[lf_name]["abstain"] += 1
                else:
                    lf_stats[lf_name]["fired"] += 1
                    if val == 1:
                        lf_stats[lf_name]["progress"] += 1
                    else:
                        lf_stats[lf_name]["stagnation"] += 1

    print(f"\n=== {label} ===")
    print(f"Total: {total}, non-short: {total_non_short}")
    results = {}
    for lf_name, s in lf_stats.items():
        t = s["fired"] + s["abstain"]
        fire_pct = round(100.0 * s["fired"] / t, 1) if t > 0 else 0
        print(f"  {lf_name}: fired={s['fired']}/{t} = {fire_pct}%  (prog={s['progress']}, stag={s['stagnation']})")
        results[lf_name] = {"fire_pct": fire_pct, "total": t, "fired": s["fired"]}
    return results, total_non_short

